import type { Href } from 'expo-router';

/**
 * Typed-route definitions are generated by the Expo dev server, so a brand-new screen is unknown to the
 * compiler until the server has run once. This keeps navigation calls compiling in the meantime.
 */
export const href = (path: string): Href => path as Href;

export const exercisePath = (id: string, pick = false) => `/train/exercise/${encodeURIComponent(id)}${pick ? '?pick=1' : ''}`;
export const LIBRARY_PATH = '/train/library';
export const PICKER_PATH = '/train/library?pick=1';
export const EDITOR_PATH = '/train/program-edit';
